pub fn manifest_owner(t: &[u8], n: usize) -> u8 {
    let u: u64 = field_str(t, n, KEY_URL, KEY_URL.len());
    if (u == NO_FIELD) {
        return OW_NONE;
    }
    return url_owner(&t[(field_start(u)) as usize..((field_start(u) + field_len(u))) as usize], field_len(u));
}

pub fn manifest_check_from(t: &[u8], n: usize, src: u8) -> u8 {
    let c: u8 = manifest_check(t, n);
    if (c != M_OK) {
        return c;
    }
    if (owner_src(manifest_owner(t, n)) != src) {
        return M_WRONG_OWNER;
    }
    return M_OK;
}

pub fn channel_parse(t: &[u8], n: usize) -> u8 {
    if ((n == 8) && starts_here(t, n, 0, "upstream", 8)) {
        return CH_UPSTREAM;
    }
    if ((n == 4) && starts_here(t, n, 0, "fork", 4)) {
        return CH_FORK;
    }
    return CH_AUTO;
}

pub fn channel_fetches(ch: u8, src: u8) -> bool {
    if (ch == CH_UPSTREAM) {
        return (src == SRC_UPSTREAM);
    }
    if (ch == CH_FORK) {
        return (src == SRC_FORK);
    }
    return ((src == SRC_UPSTREAM) || (src == SRC_FORK));
}

pub fn channel_pick(ch: u8, up_ok: bool, up_v: u64, up_b: u32, fork_ok: bool, fork_v: u64, fork_b: u32) -> u8 {
    if (ch == CH_UPSTREAM) {
        if up_ok {
            return SRC_UPSTREAM;
        }
        return SRC_NONE;
    }
    if (ch == CH_FORK) {
        if fork_ok {
            return SRC_FORK;
        }
        return SRC_NONE;
    }
    if (fork_ok && (!(up_ok) || is_newer_build(fork_v, fork_b, up_v, up_b))) {
        return SRC_FORK;
    }
    if up_ok {
        return SRC_UPSTREAM;
    }
    return SRC_NONE;
}

pub fn sums_row(t: &[u8], n: usize, name: &'static str) -> u64 {
    let mut i: usize = 0;
    while (((i + 66) + name.len()) <= n) {
        if (((at_line_start(t, i) && (t[((i + 64)) as usize] == 32)) && (t[((i + 65)) as usize] == 32)) && rl_hex_run(t, i, 64)) {
            let mut j: usize = 0;
            while ((j < name.len()) && (t[(((i + 66) + j)) as usize] == name.as_bytes()[(j) as usize])) {
                j += 1;
            }
            let e: usize = ((i + 66) + name.len());
            if ((j == name.len()) && ((e == n) || (t[(e) as usize] == 10))) {
                return (i as u64);
            }
        }
        i += 1;
    }
    return NO_FIELD;
}

pub fn sums_row_zip(t: &[u8], n: usize, v: u64) -> u64 {
    let mut i: usize = 0;
    while ((((i + 66) + 6) + 4) <= n) {
        if ((((at_line_start(t, i) && (t[((i + 64)) as usize] == 32)) && (t[((i + 65)) as usize] == 32)) && rl_hex_run(t, i, 64)) && starts_here(t, n, (i + 66), "T27OS-", 6)) {
            let mut e: usize = (i + 66);
            while ((e < n) && (t[(e) as usize] != 10)) {
                e += 1;
            }
            if ((((e - (i + 66)) > 10) && starts_here(t, n, (e - 4), ".zip", 4)) && (rl_eat_semver(t, (e - 4), (i + 72), v) == ((e - 4) as u64))) {
                return (i as u64);
            }
        }
        i += 1;
    }
    return NO_FIELD;
}

pub fn rl_row(t: &[u8], n: usize, v: u64, k: u32) -> u64 {
    if (k == 0) {
        return sums_row_zip(t, n, v);
    }
    if (k == 1) {
        return sums_row(t, n, A_T27B);
    }
    if (k == 2) {
        return sums_row(t, n, A_T27C);
    }
    if (k == 3) {
        return sums_row(t, n, A_TRI);
    }
    return sums_row(t, n, A_PTY);
}

pub fn rl_row_key(k: u32) -> &'static str {
    if (k == 0) {
        return KEY_SHA;
    }
    if (k == 1) {
        return KEY_T27B;
    }
    if (k == 2) {
        return KEY_T27C;
    }
    if (k == 3) {
        return KEY_TRI;
    }
    return KEY_PTY;
}

pub fn sums_commit(t: &[u8], n: usize) -> u64 {
    let mut i: usize = 0;
    while ((i + 47) <= n) {
        if (((at_line_start(t, i) && starts_here(t, n, i, "COMMIT ", 7)) && rl_hex_run(t, (i + 7), 40)) && (((i + 47) == n) || (t[((i + 47)) as usize] == 10))) {
            return ((i + 7) as u64);
        }
        i += 1;
    }
    return NO_FIELD;
}

pub fn rl_sha_line(out: &mut [u8], cap: usize, w: usize, key: &'static str, sums: &[u8], at: u64) -> usize {
    let mut k: usize = rl_put(out, cap, w, key);
    k = rl_put(out, cap, k, "\"");
    let a: usize = (at as usize);
    k = put_slice(out, cap, k, &sums[(a) as usize..((a + 64)) as usize], 64);
    return rl_line(out, cap, k, "\";");
}

pub fn manifest_from_sums(out: &mut [u8], cap: usize, v: u64, build: u32, sums: &[u8], sn: usize) -> usize {
    return manifest_from_sums_of(out, cap, v, build, sums, sn, OW_UPSTREAM);
}

pub fn manifest_from_sums_of(out: &mut [u8], cap: usize, v: u64, build: u32, sums: &[u8], sn: usize, ow: u8) -> usize {
    let rz: u64 = rl_row(sums, sn, v, 0);
    let rb: u64 = rl_row(sums, sn, v, 1);
    let rc: u64 = rl_row(sums, sn, v, 2);
    let rt: u64 = rl_row(sums, sn, v, 3);
    let rp: u64 = rl_row(sums, sn, v, 4);
    let cm: u64 = sums_commit(sums, sn);
    if ((((((rz == NO_FIELD) || (rb == NO_FIELD)) || (rc == NO_FIELD)) || (rt == NO_FIELD)) || (rp == NO_FIELD)) || (cm == NO_FIELD)) {
        return 0;
    }
    let mut w: usize = 0;
    w = rl_line(out, cap, w, "; T27 OS release manifest, written by specs/t27os/release.t27 manifest_from_sums. The app reads the");
    w = rl_line(out, cap, w, "; constants below and nothing else.");
    w = rl_line(out, cap, w, "module T27osReleaseManifest;");
    w = rl_put(out, cap, w, KEY_VERSION);
    w = rl_put(out, cap, w, "\"");
    w = put_semver(out, cap, w, v);
    w = rl_line(out, cap, w, "\";");
    w = rl_put(out, cap, w, KEY_BUILD);
    w = put_number(out, cap, w, build);
    w = rl_line(out, cap, w, ";");
    w = rl_sha_line(out, cap, w, KEY_SHA, sums, rz);
    w = rl_put(out, cap, w, KEY_MIN);
    w = rl_line(out, cap, w, "\"11.0\";");
    w = rl_put(out, cap, w, KEY_URL);
    w = rl_put(out, cap, w, "\"");
    w = put_zip_url_of(out, cap, w, v, build, ow);
    w = rl_line(out, cap, w, "\";");
    w = rl_put(out, cap, w, KEY_NOTES);
    w = rl_put(out, cap, w, "\"");
    w = put_notes_url_of(out, cap, w, v, build, ow);
    w = rl_line(out, cap, w, "\";");
    w = rl_put(out, cap, w, KEY_COMMIT);
    w = rl_put(out, cap, w, "\"");
    let ca: usize = (cm as usize);
    w = put_slice(out, cap, w, &sums[(ca) as usize..((ca + 40)) as usize], 40);
    w = rl_line(out, cap, w, "\";");
    w = rl_sha_line(out, cap, w, KEY_T27B, sums, rb);
    w = rl_sha_line(out, cap, w, KEY_T27C, sums, rc);
    w = rl_sha_line(out, cap, w, KEY_TRI, sums, rt);
    w = rl_sha_line(out, cap, w, KEY_PTY, sums, rp);
    return w;
}

pub fn sha_matches(computed: &[u8], computed_len: usize, wanted: &[u8], wanted_len: usize) -> bool {
    if (!(sha_ok(computed, computed_len)) || !(sha_ok(wanted, wanted_len))) {
        return false;
    }
    let mut i: usize = 0;
    while (i < 64) {
        if (computed[(i) as usize] != wanted[(i) as usize]) {
            return false;
        }
        i += 1;
    }
    return true;
}

pub const ROWS_DOWNLOADED: u32 = 4;

pub const ROWS_ALL: u32 = 5;

pub fn sums_verdict(sums: &[u8], sn: usize, man: &[u8], mn: usize, first: u32, last: u32) -> u32 {
    let ver: u64 = manifest_version(man, mn);
    if (ver == NO_VERSION) {
        return (first + 1);
    }
    let mut k: u32 = first;
    while (k < last) {
        let key: &'static str = rl_row_key(k);
        let f: u64 = field_str(man, mn, key, key.len());
        let r: u64 = rl_row(sums, sn, ver, k);
        if ((f == NO_FIELD) || (r == NO_FIELD)) {
            return (k + 1);
        }
        let a: usize = (r as usize);
        if !(sha_matches(&sums[(a) as usize..((a + 64)) as usize], 64, &man[(field_start(f)) as usize..((field_start(f) + field_len(f))) as usize], field_len(f))) {
            return (k + 1);
        }
        k += 1;
    }
    return 0;
}

pub fn version_text(out: &mut [u8], cap: usize, name: &'static str, ver: &'static str, build: u32, commit: &'static str) -> usize {
    let mut w: usize = rl_put(out, cap, 0, name);
    w = rl_put(out, cap, w, " ");
    w = rl_put(out, cap, w, ver);
    w = rl_line(out, cap, w, "");
    w = rl_put(out, cap, w, "build ");
    w = put_number(out, cap, w, build);
    w = rl_put(out, cap, w, " commit ");
    w = rl_put(out, cap, w, commit);
    return rl_line(out, cap, w, "");
}

pub fn version_commit(t: &[u8], n: usize) -> u64 {
    let mut i: usize = 0;
    while ((i + 8) <= n) {
        if starts_here(t, n, i, " commit ", 8) {
            let s: usize = (i + 8);
            let mut e: usize = s;
            while ((e < n) && (t[(e) as usize] > 32)) {
                e += 1;
            }
            if (e == s) {
                return NO_FIELD;
            }
            return (((s as u64) << 32) | ((e - s) as u64));
        }
        i += 1;
    }
    return NO_FIELD;
}

pub const TV_OK: u8 = 0;

pub const TV_NO_COMMIT: u8 = 1;

pub const TV_DIFFERS: u8 = 2;

pub fn tool_verdict(vt: &[u8], n: usize, want: &[u8], want_n: usize) -> u8 {
    let f: u64 = version_commit(vt, n);
    if ((f == NO_FIELD) || !(commit_ok(want, want_n))) {
        return TV_NO_COMMIT;
    }
    let s: usize = field_start(f);
    let l: usize = field_len(f);
    if (((l < 7) || (l > 40)) || !(rl_hex_run(vt, s, l))) {
        return TV_NO_COMMIT;
    }
    let mut i: usize = 0;
    while (i < l) {
        if (vt[((s + i)) as usize] != want[(i) as usize]) {
            return TV_DIFFERS;
        }
        i += 1;
    }
    return TV_OK;
}

pub fn tv_worse(a: u8, b: u8) -> u8 {
    if ((a == TV_DIFFERS) || (b == TV_DIFFERS)) {
        return TV_DIFFERS;
    }
    if ((a == TV_NO_COMMIT) || (b == TV_NO_COMMIT)) {
        return TV_NO_COMMIT;
    }
    return TV_OK;
}

pub const ID_INSTALL: u8 = 0;

pub const ID_REFUSE_SHA: u8 = 1;

pub const ID_REFUSE_COMMIT: u8 = 2;

pub const ID_REFUSE_NO_COMMIT: u8 = 3;

pub const ID_REFUSE_BUNDLE: u8 = 4;

pub fn install_decision(sums_bad: u32, tools: u8, bundle_ok: bool) -> u8 {
    if (sums_bad != 0) {
        return ID_REFUSE_SHA;
    }
    if (tools == TV_DIFFERS) {
        return ID_REFUSE_COMMIT;
    }
    if (tools == TV_NO_COMMIT) {
        return ID_REFUSE_NO_COMMIT;
    }
    if !(bundle_ok) {
        return ID_REFUSE_BUNDLE;
    }
    return ID_INSTALL;
}

pub const UPD_POLL_S: u64 = 3600;

pub const UPD_BACKOFF_MAX_S: u64 = 14400;

pub const UPD_BACKOFF_STEPS: u32 = 3;

pub const UPD_FAILS_MAX: u32 = 8;

pub const CONFIRM_AFTER_S: u64 = 60;

pub const SWAP_QUIET_S: u64 = 60;

pub const TOAST_S: u64 = 10;

pub fn poll_gap(fails: u32) -> u64 {
    let mut k: u32 = fails;
    if (k > UPD_BACKOFF_STEPS) {
        k = UPD_BACKOFF_STEPS;
    }
    let mut g: u64 = (UPD_POLL_S << (k as u64));
    if (g > UPD_BACKOFF_MAX_S) {
        g = UPD_BACKOFF_MAX_S;
    }
    return g;
}

pub fn fails_after(ok: bool, fails: u32) -> u32 {
    if ok {
        return 0;
    }
    if (fails >= UPD_FAILS_MAX) {
        return UPD_FAILS_MAX;
    }
    return (fails + 1);
}

pub fn check_due(now: u64, last_check: u64, fails: u32) -> bool {
    if (last_check == 0) {
        return true;
    }
    if (now < last_check) {
        return true;
    }
    return ((now - last_check) >= poll_gap(fails));
}

pub fn toast_on(now: u64, since: u64) -> bool {
    if (since == 0) {
        return false;
    }
    return ((now >= since) && ((now - since) < TOAST_S));
}

pub fn toast_text(out: &mut [u8], cap: usize, v: u64, build: u32) -> usize {
    let mut w: usize = rl_put(out, cap, 0, "updated to ");
    w = put_semver(out, cap, w, v);
    w = rl_put(out, cap, w, " b");
    return put_number(out, cap, w, build);
}

pub fn idle_enough(busy_panes: u32) -> bool {
    return (busy_panes == 0);
}

pub fn swap_ready(state: u8, busy_panes: u32, quiet_s: u64, pressed: bool) -> bool {
    if ((state != U_STAGED) || !(idle_enough(busy_panes))) {
        return false;
    }
    return (pressed || (quiet_s >= SWAP_QUIET_S));
}

pub fn is_newer_build(cand_v: u64, cand_b: u32, cur_v: u64, cur_b: u32) -> bool {
    if ((cand_v == NO_VERSION) || (cur_v == NO_VERSION)) {
        return false;
    }
    if (cand_v != cur_v) {
        return (cand_v > cur_v);
    }
    return (cand_b > cur_b);
}

pub const OFFER_NONE: u8 = 0;

pub const OFFER_UPDATE: u8 = 1;

pub const OFFER_BAD_MANIFEST: u8 = 2;

pub const OFFER_OLD_MACOS: u8 = 3;

pub const OFFER_REJECTED: u8 = 4;

pub fn offer(check: u8, cand_v: u64, cand_b: u32, cur_v: u64, cur_b: u32, rejected_b: u32, os_ok: bool) -> u8 {
    if (check != M_OK) {
        return OFFER_BAD_MANIFEST;
    }
    if !(is_newer_build(cand_v, cand_b, cur_v, cur_b)) {
        return OFFER_NONE;
    }
    if ((rejected_b != 0) && (cand_b == rejected_b)) {
        return OFFER_REJECTED;
    }
    if !(os_ok) {
        return OFFER_OLD_MACOS;
    }
    return OFFER_UPDATE;
}

pub const U_IDLE: u8 = 0;

pub const U_CHECKING: u8 = 1;

pub const U_DOWNLOADING: u8 = 2;

pub const U_VERIFYING: u8 = 3;

pub const U_STAGED: u8 = 4;

pub const U_SWAPPED: u8 = 5;

pub const EV_CHECK: u8 = 0;

pub const EV_OFFER: u8 = 1;

pub const EV_NO_OFFER: u8 = 2;

pub const EV_DOWNLOADED: u8 = 3;

pub const EV_FAILED: u8 = 4;

pub const EV_SHA_OK: u8 = 5;

pub const EV_SHA_BAD: u8 = 6;

pub const EV_SIGNED: u8 = 7;

pub const EV_SWAP: u8 = 8;

pub fn update_step(state: u8, event: u8, busy_panes: u32) -> u8 {
    if (((event == EV_FAILED) || (event == EV_SHA_BAD)) || (event == EV_NO_OFFER)) {
        return U_IDLE;
    }
    if ((state == U_IDLE) && (event == EV_CHECK)) {
        return U_CHECKING;
    }
    if ((state == U_CHECKING) && (event == EV_OFFER)) {
        return U_DOWNLOADING;
    }
    if ((state == U_DOWNLOADING) && (event == EV_DOWNLOADED)) {
        return U_VERIFYING;
    }
    if ((state == U_VERIFYING) && (event == EV_SHA_OK)) {
        return U_VERIFYING;
    }
    if ((state == U_VERIFYING) && (event == EV_SIGNED)) {
        return U_STAGED;
    }
    if ((state == U_STAGED) && (event == EV_SWAP)) {
        if idle_enough(busy_panes) {
            return U_SWAPPED;
        }
        return U_STAGED;
    }
    return state;
}

pub const MK_NONE: u8 = 0;

pub const MK_SWAPPED: u8 = 1;

pub const MK_STARTED: u8 = 2;

pub fn marker_of(has_byte: bool, b: u8) -> u8 {
    if !(has_byte) {
        return MK_NONE;
    }
    if (b == b'1') {
        return MK_SWAPPED;
    }
    if (b == b'2') {
        return MK_STARTED;
    }
    return MK_NONE;
}

pub const BOOT_RUN: u8 = 0;

pub const BOOT_ROLLBACK: u8 = 1;

pub const BOOT_BROKEN: u8 = 2;

pub const BOOT_FIRST: u8 = 3;

pub fn boot_action(marker: u8, previous_kept: bool) -> u8 {
    if (marker == MK_NONE) {
        return BOOT_RUN;
    }
    if (marker == MK_SWAPPED) {
        return BOOT_FIRST;
    }
    if previous_kept {
        return BOOT_ROLLBACK;
    }
    return BOOT_BROKEN;
}

pub fn confirm_due(uptime_s: u64) -> bool {
    return (uptime_s >= CONFIRM_AFTER_S);
}

pub fn previous_after(swapped: bool, rolled_back: bool, previous_kept: bool) -> bool {
    if rolled_back {
        return false;
    }
    if swapped {
        return true;
    }
    return previous_kept;
}

pub fn rejected_after(boot: u8, running_b: u32, rejected_b: u32) -> u32 {
    if (boot == BOOT_ROLLBACK) {
        return running_b;
    }
    return rejected_b;
}

pub const WHY_NONE: u8 = 0;

pub const WHY_OFFLINE: u8 = 1;

pub const WHY_MANIFEST: u8 = 2;

pub const WHY_DOWNLOAD: u8 = 3;

pub const WHY_SHA: u8 = 4;

pub const WHY_STAGE: u8 = 5;

pub const WHY_COMMIT: u8 = 6;

pub const WHY_NO_COMMIT: u8 = 7;

pub const WHY_BUNDLE: u8 = 8;

pub const WHY_SWAP: u8 = 9;

pub const WHY_BROKEN: u8 = 10;

pub fn why_of_decision(d: u8) -> u8 {
    if (d == ID_REFUSE_SHA) {
        return WHY_SHA;
    }
    if (d == ID_REFUSE_COMMIT) {
        return WHY_COMMIT;
    }
    if (d == ID_REFUSE_NO_COMMIT) {
        return WHY_NO_COMMIT;
    }
    if (d == ID_REFUSE_BUNDLE) {
        return WHY_BUNDLE;
    }
    return WHY_NONE;
}

pub const STRIP_HIDDEN: u8 = 0;

pub const STRIP_PROGRESS: u8 = 1;

pub const STRIP_READY: u8 = 2;

pub const STRIP_FAILED: u8 = 3;

pub fn strip_kind(state: u8, why: u8) -> u8 {
    if (((state == U_DOWNLOADING) || (state == U_VERIFYING)) || (state == U_SWAPPED)) {
        return STRIP_PROGRESS;
    }
    if (state == U_STAGED) {
        return STRIP_READY;
    }
    if ((state == U_IDLE) && (why >= WHY_MANIFEST)) {
        return STRIP_FAILED;
    }
    return STRIP_HIDDEN;
}

pub fn rl_why_text(why: u8) -> &'static str {
    if (why == WHY_MANIFEST) {
        return "the manifest is not valid";
    }
    if (why == WHY_DOWNLOAD) {
        return "the download failed";
    }
    if (why == WHY_SHA) {
        return "a sha256 differs from the manifest";
    }
    if (why == WHY_STAGE) {
        return "unzip or code signature failed";
    }
    if (why == WHY_COMMIT) {
        return "the toolchain is from another commit";
    }
    if (why == WHY_NO_COMMIT) {
        return "the toolchain names no commit";
    }
    if (why == WHY_BUNDLE) {
        return "this copy is not an installed app";
    }
    if (why == WHY_SWAP) {
        return "the swap failed, the old app stays";
    }
    if (why == WHY_BROKEN) {
        return "the last update did not start; rolled back";
    }
    return "";
}

pub fn strip_text(out: &mut [u8], cap: usize, state: u8, why: u8, build: u32, busy_panes: u32) -> usize {
    let mut w: usize = 0;
    if (state == U_DOWNLOADING) {
        w = rl_put(out, cap, w, "UPDATING: downloading build ");
        return put_number(out, cap, w, build);
    }
    if (state == U_VERIFYING) {
        w = rl_put(out, cap, w, "UPDATING: verifying build ");
        return put_number(out, cap, w, build);
    }
    if (state == U_SWAPPED) {
        return rl_put(out, cap, w, "UPDATING: restarting");
    }
    if (state == U_STAGED) {
        if !(idle_enough(busy_panes)) {
            w = rl_put(out, cap, w, "UPDATE READY build ");
            w = put_number(out, cap, w, build);
            return rl_put(out, cap, w, " (panes busy)");
        }
        w = rl_put(out, cap, w, "UPDATE NOW build ");
        return put_number(out, cap, w, build);
    }
    if (strip_kind(state, why) == STRIP_FAILED) {
        w = rl_put(out, cap, w, "UPDATE FAILED: ");
        return rl_put(out, cap, w, rl_why_text(why));
    }
    return 0;
}

pub fn parse_build(t: &[u8], n: usize) -> u32 {
    if ((n == 0) || (n > 9)) {
        return 0;
    }
    let mut v: u32 = 0;
    let mut i: usize = 0;
    while (i < n) {
        if ((t[(i) as usize] < b'0') || (t[(i) as usize] > b'9')) {
            return 0;
        }
        v = ((v * 10) + ((t[(i) as usize] - b'0') as u32));
        i += 1;
    }
    return v;
}

pub const SERVER_LABEL: &'static str = "ai.t27.os.pty";

pub const SERVER_PATH: &'static str = "$HOME/.t27os/bin:$HOME/.local/bin:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin";

pub fn path_ok(t: &[u8], n: usize) -> bool {
    if (n == 0) {
        return false;
    }
    let mut i: usize = 0;
    while (i < n) {
        let c: u8 = t[(i) as usize];
        if !(((((((((((c >= b'0') && (c <= b'9')) || ((c >= b'a') && (c <= b'z'))) || ((c >= b'A') && (c <= b'Z'))) || (c == b'/')) || (c == b'.')) || (c == b'_')) || (c == b'+')) || (c == b'@')) || (c == b'-'))) {
            return false;
        }
        i += 1;
    }
    return true;
}

pub fn dev_path(t: &[u8], n: usize) -> bool {
    let mut i: usize = 0;
    while ((i + 8) <= n) {
        if starts_here(t, n, i, "/target/", 8) {
            return true;
        }
        i += 1;
    }
    return false;
}

pub fn quoted_path_ok(t: &[u8], n: usize) -> bool {
    if (((n < 2) || (n > 400)) || (t[0] != 47)) {
        return false;
    }
    let mut i: usize = 0;
    while (i < n) {
        let c: u8 = t[(i) as usize];
        if ((((((c < 32) || (c > 126)) || (c == 34)) || (c == 36)) || (c == 96)) || (c == 92)) {
            return false;
        }
        i += 1;
    }
    return true;
}

pub fn bundle_len(exe: &[u8], n: usize) -> usize {
    let tail: usize = 21;
    if (((n <= (tail + 4)) || !(quoted_path_ok(exe, n))) || dev_path(exe, n)) {
        return 0;
    }
    if !(starts_here(exe, n, (n - tail), "/Contents/MacOS/T27OS", tail)) {
        return 0;
    }
    if !(starts_here(exe, n, ((n - tail) - 4), ".app", 4)) {
        return 0;
    }
    return (n - tail);
}

pub fn rl_head(out: &mut [u8], cap: usize, home: &[u8], hn: usize) -> usize {
    let mut w: usize = rl_put(out, cap, 0, "export HOME=\"");
    w = put_slice(out, cap, w, home, hn);
    return rl_put(out, cap, w, "\"; export PATH=/usr/bin:/bin:/usr/sbin:/sbin:/opt/homebrew/bin:/usr/local/bin; U=$HOME/.t27os/updates; mkdir -p $U/previous $HOME/.t27os/bin; ");
}

pub fn rl_server_start(out: &mut [u8], cap: usize, w: usize) -> usize {
    let mut k: usize = rl_put(out, cap, w, "launchctl remove ");
    k = rl_put(out, cap, k, SERVER_LABEL);
    k = rl_put(out, cap, k, " 2>/dev/null; launchctl submit -l ");
    k = rl_put(out, cap, k, SERVER_LABEL);
    k = rl_put(out, cap, k, " -- /usr/bin/env PATH=\"");
    k = rl_put(out, cap, k, SERVER_PATH);
    return rl_put(out, cap, k, "\" HOME=\"$HOME\" $HOME/.t27os/t27os-pty");
}

pub fn rl_server_restart(out: &mut [u8], cap: usize, w: usize) -> usize {
    let k: usize = rl_put(out, cap, w, "pkill -x t27os-pty 2>/dev/null; sleep 1; ");
    return rl_server_start(out, cap, k);
}

pub fn server_restart_text(out: &mut [u8], cap: usize) -> usize {
    return rl_server_restart(out, cap, 0);
}

pub const LIVE_ASSET: &'static str = "t27os-live.t27";

pub const LIVE_URL: &'static str = "https://github.com/gHashTag/t27/releases/download/t27os-latest/t27os-live.t27";

pub const LIVE_DIR: &'static str = "/.t27os/live/";

pub const F_LIVE: &'static str = "live.t27";

pub fn rl_fetch(out: &mut [u8], cap: usize, w: usize, url: &'static str, dst: &'static str) -> usize {
    let mut k: usize = rl_put(out, cap, w, "[ -s ");
    k = rl_put(out, cap, k, dst);
    k = rl_put(out, cap, k, " ] || rm -f ");
    k = rl_put(out, cap, k, dst);
    k = rl_put(out, cap, k, ".etag; rm -f ");
    k = rl_put(out, cap, k, dst);
    k = rl_put(out, cap, k, ".tmp; curl -fsSL --max-time 20 --etag-save ");
    k = rl_put(out, cap, k, dst);
    k = rl_put(out, cap, k, ".etag --etag-compare ");
    k = rl_put(out, cap, k, dst);
    k = rl_put(out, cap, k, ".etag -o ");
    k = rl_put(out, cap, k, dst);
    k = rl_put(out, cap, k, ".tmp ");
    k = rl_put(out, cap, k, url);
    k = rl_put(out, cap, k, "; R=$?; [ -s ");
    k = rl_put(out, cap, k, dst);
    k = rl_put(out, cap, k, ".tmp ] && mv -f ");
    k = rl_put(out, cap, k, dst);
    k = rl_put(out, cap, k, ".tmp ");
    return rl_put(out, cap, k, dst);
}

pub fn check_cmd(out: &mut [u8], cap: usize, home: &[u8], hn: usize, ch: u8) -> usize {
    let mut w: usize = rl_head(out, cap, home, hn);
    w = rl_put(out, cap, w, "mkdir -p $HOME/.t27os/live; ");
    w = rl_fetch(out, cap, w, LIVE_URL, "$HOME/.t27os/live/live.t27");
    let up: bool = channel_fetches(ch, SRC_UPSTREAM);
    let fk: bool = channel_fetches(ch, SRC_FORK);
    if up {
        w = rl_put(out, cap, w, "; ");
        w = rl_fetch(out, cap, w, MANIFEST_URL, "$U/manifest.t27");
    }
    if (up && fk) {
        w = rl_put(out, cap, w, "; A=$R");
    }
    if fk {
        w = rl_put(out, cap, w, "; ");
        w = rl_fetch(out, cap, w, MANIFEST_URL_FORK, "$U/manifest-fork.t27");
    }
    if (up && fk) {
        w = rl_put(out, cap, w, "; [ $A = 0 ] && R=0");
    }
    w = rl_put(out, cap, w, "; [ -x $HOME/.t27os/t27os-pty ] && ! pgrep -x t27os-pty >/dev/null && { ");
    w = rl_server_start(out, cap, w);
    return rl_put(out, cap, w, "; }; exit $R");
}

pub fn download_cmd(out: &mut [u8], cap: usize, home: &[u8], hn: usize, v: u64, build: u32, ow: u8) -> usize {
    let mut w: usize = rl_head(out, cap, home, hn);
    w = rl_put(out, cap, w, "B=$U/");
    w = put_number(out, cap, w, build);
    w = rl_put(out, cap, w, "; rm -rf $B; mkdir -p $B; cd $B || exit 1; D=");
    w = put_base_of(out, cap, w, v, build, ow);
    w = rl_put(out, cap, w, "; F=\"");
    w = put_zip_name(out, cap, w, v);
    w = rl_put(out, cap, w, " ");
    w = rl_put(out, cap, w, A_T27B);
    w = rl_put(out, cap, w, " ");
    w = rl_put(out, cap, w, A_T27C);
    w = rl_put(out, cap, w, " ");
    w = rl_put(out, cap, w, A_TRI);
    return rl_put(out, cap, w, "\"; for f in $F; do curl -fsSL --max-time 600 -o $f $D$f || exit 1; done; shasum -a 256 $F > sums.txt");
}

pub fn stage_cmd(out: &mut [u8], cap: usize, home: &[u8], hn: usize, v: u64, build: u32) -> usize {
    let mut w: usize = rl_head(out, cap, home, hn);
    w = rl_put(out, cap, w, "B=$U/");
    w = put_number(out, cap, w, build);
    w = rl_put(out, cap, w, "; cd $B || exit 1; rm -rf stage; ditto -x -k --norsrc ");
    w = put_zip_name(out, cap, w, v);
    w = rl_put(out, cap, w, " stage && find stage -name '._*' -delete && xattr -cr stage && chmod +x ");
    w = rl_put(out, cap, w, A_T27B);
    w = rl_put(out, cap, w, " ");
    w = rl_put(out, cap, w, A_T27C);
    w = rl_put(out, cap, w, " ");
    w = rl_put(out, cap, w, A_TRI);
    w = rl_put(out, cap, w, " && codesign --force --deep -s - stage/T27OS/T27OS.app && codesign -v stage/T27OS/T27OS.app && (cd stage/T27OS && shasum -a 256 t27os-pty) > sums2.txt && ./");
    w = rl_put(out, cap, w, A_T27B);
    w = rl_put(out, cap, w, " --version > v_t27b.txt 2>&1 && ./");
    w = rl_put(out, cap, w, A_T27C);
    w = rl_put(out, cap, w, " --version > v_t27c.txt 2>&1 && ./");
    w = rl_put(out, cap, w, A_TRI);
    return rl_put(out, cap, w, " --version > v_tri.txt 2>&1");
}

pub fn swap_cmd(out: &mut [u8], cap: usize, home: &[u8], hn: usize, bundle: &[u8], bn: usize, build: u32) -> usize {
    let mut w: usize = rl_head(out, cap, home, hn);
    w = rl_put(out, cap, w, "B=$U/");
    w = put_number(out, cap, w, build);
    w = rl_put(out, cap, w, "; N=$B/stage/T27OS; BIN=$HOME/.t27os/bin; P=$HOME/.t27os/t27os-pty; A=\"");
    w = put_slice(out, cap, w, bundle, bn);
    w = rl_put(out, cap, w, "\"; OLD=$(shasum -a 256 < $P 2>/dev/null); ");
    w = rl_put(out, cap, w, "for t in t27b t27c tri; do cp $B/$t-darwin-arm64 $BIN/$t.new || exit 1; [ ! -f $BIN/$t ] || cp -p $BIN/$t $BIN/$t.prev; done; ");
    w = rl_put(out, cap, w, "cp $N/t27os-pty $P.new && chmod 700 $P.new || exit 1; [ ! -f $P ] || { cp -p $P $P.prev && chmod 700 $P.prev; }; ");
    w = rl_put(out, cap, w, "rm -rf $U/previous/T27OS.app; echo 1 > $U/pending; ");
    w = rl_put(out, cap, w, "mv \"$A\" $U/previous/T27OS.app || { rm -f $U/pending; exit 1; }; ");
    w = rl_put(out, cap, w, "mv $N/T27OS.app \"$A\" || { mv $U/previous/T27OS.app \"$A\"; rm -f $U/pending; exit 1; }; echo 1 > $U/previous/kept; ");
    w = rl_put(out, cap, w, "for t in t27b t27c tri; do mv -f $BIN/$t.new $BIN/$t; done; mv -f $P.new $P; ");
    w = rl_put(out, cap, w, "NEW=$(shasum -a 256 < $P); [ \"$OLD\" = \"$NEW\" ] || { ");
    w = rl_server_restart(out, cap, w);
    return rl_put(out, cap, w, "; }; touch \"$A/Contents/MacOS/T27OS\"");
}

pub fn mark_cmd(out: &mut [u8], cap: usize, home: &[u8], hn: usize) -> usize {
    let w: usize = rl_head(out, cap, home, hn);
    return rl_put(out, cap, w, "echo 2 > $U/pending");
}

pub fn confirm_cmd(out: &mut [u8], cap: usize, home: &[u8], hn: usize) -> usize {
    let w: usize = rl_head(out, cap, home, hn);
    return rl_put(out, cap, w, "rm -f $U/pending");
}

pub fn rollback_cmd(out: &mut [u8], cap: usize, home: &[u8], hn: usize, bundle: &[u8], bn: usize, build: u32) -> usize {
    let mut w: usize = rl_head(out, cap, home, hn);
    w = rl_put(out, cap, w, "BIN=$HOME/.t27os/bin; A=\"");
    w = put_slice(out, cap, w, bundle, bn);
    w = rl_put(out, cap, w, "\"; echo ");
    w = put_number(out, cap, w, build);
    w = rl_put(out, cap, w, " > $U/rejected; rm -rf $U/bad.app; mv \"$A\" $U/bad.app && mv $U/previous/T27OS.app \"$A\" && rm -f $U/pending $U/previous/kept; ");
    w = rl_put(out, cap, w, "for t in t27b t27c tri; do [ ! -f $BIN/$t.prev ] || mv -f $BIN/$t.prev $BIN/$t; done; touch \"$A/Contents/MacOS/T27OS\"");
    return w;
}

